import{_ as o,o as a,c as e,a2 as r}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Сжатие контекста","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/compaction.md","filePath":"ru/guides/compaction.md","lastUpdated":1792323081000}'),n={name:"ru/guides/compaction.md"};function i(s,t,d,l,h,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="сжатие-контекста" tabindex="-1">Сжатие контекста <a class="header-anchor" href="#сжатие-контекста" aria-label="Permalink to &quot;Сжатие контекста&quot;">​</a></h1><p><strong>Сжатие контекста</strong> уменьшает «вес» промпта одной сессии разговора: старые ходы сворачиваются в сводку, и активный контекст остаётся меньше.</p><p>Эта страница — про <strong>контекст сессии</strong>, а не про хранилище долговременной памяти. Если вы хотите объединить или переписать сохранённые воспоминания в провайдере памяти, см. <a href="./memory.html">Управление памятью Bot</a>.</p><hr><h2 id="сжатие-включено-по-умолчанию" tabindex="-1">Сжатие включено по умолчанию <a class="header-anchor" href="#сжатие-включено-по-умолчанию" aria-label="Permalink to &quot;Сжатие включено по умолчанию&quot;">​</a></h2><p>Новые Bot поставляются с автоматическим сжатием контекста — <strong>включённым и без настройки</strong>. Вам не нужно выбирать порог, коэффициент или модель-суммаризатор: Memoh рассчитывает всё относительно <code>context_window</code> чат-модели:</p><ul><li>Когда сжимаемая история сессии переходит примерно <strong>50%</strong> контекстного окна модели, Memoh сжимает её в <strong>фоне</strong> после хода.</li><li>Если сессия выросла дальше примерно <strong>75%</strong>, прежде чем фоновый проход успел отработать, Memoh сжимает <strong>синхронно</strong>, перед отправкой следующего хода.</li><li>Оба пути стремятся вернуть «сырую» историю примерно к <strong>40%</strong> окна.</li></ul><p>Единственное настоящее условие: чат-модель Bot должна объявлять <code>context_window</code> в настройках модели. Без него у автоматической политики нет бюджета, от которого можно отталкиваться, и она никогда не срабатывает. См. <a href="./../integrations/providers/llm.html">Провайдеры и модели</a>.</p><p>Bot, созданные до смены этого умолчания, сохраняют свои настройки и ведут себя так, как настроены (см. режим legacy ниже).</p><hr><h2 id="настроика" tabindex="-1">Настройка <a class="header-anchor" href="#настроика" aria-label="Permalink to &quot;Настройка&quot;">​</a></h2><p>Настройки сжатия у Bot по-прежнему есть — для подстройки и переопределений:</p><table tabindex="0"><thead><tr><th>Поле</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Compaction Enabled</strong></td><td>Включено по умолчанию. Выключите, чтобы отключить автоматическое сжатие для этого Bot.</td></tr><tr><td><strong>Compaction Threshold</strong></td><td>Порог входных токенов. <code>0</code> (по умолчанию) означает автоматическую политику относительно модели, описанную выше. Значение <strong>больше 0</strong> переключает в legacy-режим с абсолютным порогом.</td></tr><tr><td><strong>Compaction Ratio</strong></td><td>Насколько агрессивно сокращать сессию. Используется только в legacy-режиме — пока порог равен <code>0</code>, поле скрыто.</td></tr><tr><td><strong>Compaction Model</strong></td><td>Необязательная выделенная модель-суммаризатор. По умолчанию — чат-модель; переопределение можно сбросить обратно в <strong>Use chat model (default)</strong>.</td></tr></tbody></table><h3 id="выбор-модели-сжатия" tabindex="-1">Выбор модели сжатия <a class="header-anchor" href="#выбор-модели-сжатия" aria-label="Permalink to &quot;Выбор модели сжатия&quot;">​</a></h3><p>Суммаризировать может любая включённая чат-модель, с одним ограничением: провайдер должен уважать лимиты выходных токенов. <strong>Модели OpenAI Codex суммаризатором быть не могут</strong> — выпадающий список моделей их отфильтровывает.</p><p>Это важно, когда основная чат-модель Bot — модель Codex: автоматическое сжатие тихо бездействует, потому что наследовать нечего. В этом случае назначьте явную <strong>Compaction Model</strong>.</p><hr><h2 id="немедленное-сжатие" tabindex="-1">Немедленное сжатие <a class="header-anchor" href="#немедленное-сжатие" aria-label="Permalink to &quot;Немедленное сжатие&quot;">​</a></h2><p>Запустить сжатие текущей сессии немедленно можно двумя способами:</p><h3 id="из-панели-состояния-сессии" tabindex="-1">Из панели состояния сессии <a class="header-anchor" href="#из-панели-состояния-сессии" aria-label="Permalink to &quot;Из панели состояния сессии&quot;">​</a></h3><ol><li>Откройте активный разговор.</li><li>Откройте панель состояния сессии.</li><li>Нажмите <strong>Compact Now</strong>.</li></ol><p>Панель состояния также показывает текущее использование контекста, долю попаданий в кэш и использованные навыки — это помогает решить, полезно ли сжатие прямо сейчас.</p><h3 id="из-слэш-команд" tabindex="-1">Из слэш-команд <a class="header-anchor" href="#из-слэш-команд" aria-label="Permalink to &quot;Из слэш-команд&quot;">​</a></h3><p>Выполните:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/compact</span></span></code></pre></div><p>или:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/compact run</span></span></code></pre></div><p>Ручное сжатие сжимает столько сессии, сколько возможно (а не останавливается на автоматической цели), и обходит короткую паузу, которую автоматическое сжатие выдерживает после неудачной попытки.</p><hr><h2 id="что-сжатие-сохраняет" tabindex="-1">Что сжатие сохраняет <a class="header-anchor" href="#что-сжатие-сохраняет" aria-label="Permalink to &quot;Что сжатие сохраняет&quot;">​</a></h2><p>Суммаризатор работает с типизированными записями разговора, что сохраняет верность сводки:</p><ul><li>Вызовы инструментов и их результаты никогда не разделяются — обмен с инструментом либо целиком остаётся в «сырой» истории, либо целиком суммаризируется.</li><li>Медиа сводятся к меткам <code>[image]</code> / <code>[file]</code>, а не к «сырым» данным.</li><li>Сводки, которые пришли пустыми, обрезанными или оказались не меньше оригинала, отклоняются, а не сохраняются.</li><li>В сессиях, работающих на нескольких рабочих пространствах, сводка помнит, на каком рабочем пространстве происходила каждая часть разговора.</li></ul><p>Сжатие применяется к обычным чат-сессиям, а также к разговорам типа <strong>discuss</strong> и конвейерным (pipeline) разговорам.</p><hr><h2 id="состояние-и-журналы" tabindex="-1">Состояние и журналы <a class="header-anchor" href="#состояние-и-журналы" aria-label="Permalink to &quot;Состояние и журналы&quot;">​</a></h2><p>Вкладка <strong>Compaction</strong> на странице Bot даёт журнал прогонов сжатия контекста.</p><p>Типичные поля:</p><ul><li><strong>Status</strong> — завершилось сжатие успешно или с ошибкой</li><li><strong>Summary</strong> — текст сводки или её предпросмотр</li><li><strong>Message Count</strong> — сколько сообщений было задействовано</li><li><strong>Started / Completed Time</strong> — когда прогон произошёл</li><li><strong>Model / Usage</strong> — метаданные о модели и расходе токенов, когда они доступны</li></ul><p>Список записей полезен, когда нужно убедиться, что автоматическое сжатие действительно работает, или разобраться в сбое.</p><h3 id="частые-причины-сбоев" tabindex="-1">Частые причины сбоев <a class="header-anchor" href="#частые-причины-сбоев" aria-label="Permalink to &quot;Частые причины сбоев&quot;">​</a></h3><p>Когда сжатие не может выполниться, Memoh сообщает <code>compaction.model_unavailable</code> с конкретной причиной: модель сжатия не настроена, не является чат-моделью, отключена, отключён её провайдер, провайдер не поддерживает лимиты вывода (Codex) или у модели нет известного контекстного окна. <code>/compact</code> сообщает те же состояния прямо в чате.</p><hr><h2 id="связь-с-context-window" tabindex="-1">Связь с <code>context_window</code> <a class="header-anchor" href="#связь-с-context-window" aria-label="Permalink to &quot;Связь с `context_window`&quot;">​</a></h2><p>Memoh отслеживает текущую сессию относительно <code>context_window</code> выбранной чат-модели.</p><p>Это видно:</p><ul><li>в панели состояния сессии в приложении</li><li>в слэш-команде <code>/status</code></li></ul><p>Использование контекста — оценка (примерно четыре символа на токен), так что воспринимайте проценты как ориентир, а не точные числа.</p><hr><h2 id="сжатие-контекста-и-сжатие-памяти" tabindex="-1">Сжатие контекста и сжатие памяти <a class="header-anchor" href="#сжатие-контекста-и-сжатие-памяти" aria-label="Permalink to &quot;Сжатие контекста и сжатие памяти&quot;">​</a></h2><p>Эти две функции звучат похоже, но решают разные задачи:</p><table tabindex="0"><thead><tr><th>Функция</th><th>Область</th><th>Триггер</th><th>Результат</th></tr></thead><tbody><tr><td><strong>Сжатие контекста</strong></td><td>Одна активная сессия</td><td>Автоматически, панель сессии или <code>/compact</code></td><td>Суммаризирует старую историю чата для будущих ходов</td></tr><tr><td><strong>Сжатие памяти</strong></td><td>Провайдер долговременной памяти</td><td>Вкладка <strong>Memory</strong></td><td>Переписывает сохранённые записи памяти</td></tr></tbody></table><p>Используйте <strong>сжатие контекста</strong>, когда один разговор стал слишком большим.</p><p>Используйте <strong>сжатие памяти</strong>, когда зашумлёнными или избыточными стали сами сохранённые воспоминания Bot.</p><hr><h2 id="дальнеишие-шаги" tabindex="-1">Дальнейшие шаги <a class="header-anchor" href="#дальнеишие-шаги" aria-label="Permalink to &quot;Дальнейшие шаги&quot;">​</a></h2><ul><li>Сведения о сессии во время выполнения — см. <a href="./sessions.html">Сессии</a>.</li><li>Сжатие по слэш-команде — см. <a href="./slash-commands.html">Слэш-команды</a>.</li><li>Управление долговременной памятью вместо контекста сессии — см. <a href="./memory.html">Управление памятью Bot</a>.</li></ul>',56)])])}const m=o(n,[["render",i]]);export{g as __pageData,m as default};
